-- Base d'entraînement SQL — CPAM fictive — v1 (données 100 % fictives)
-- Compatible SQLite, PostgreSQL et MySQL (types simples, dates au format AAAA-MM-JJ)
DROP TABLE IF EXISTS controles;
DROP TABLE IF EXISTS prestations;
DROP TABLE IF EXISTS paiements_ij;
DROP TABLE IF EXISTS arrets_travail;
DROP TABLE IF EXISTS assures;
DROP TABLE IF EXISTS employeurs;
DROP TABLE IF EXISTS professionnels_sante;
DROP TABLE IF EXISTS ref_actes;

CREATE TABLE ref_actes (
  code_acte TEXT PRIMARY KEY, libelle TEXT NOT NULL, categorie TEXT NOT NULL,
  tarif_base REAL NOT NULL, taux_remboursement INTEGER NOT NULL);
CREATE TABLE professionnels_sante (
  id_ps TEXT PRIMARY KEY, specialite TEXT NOT NULL, secteur_conventionnel TEXT NOT NULL,
  departement TEXT NOT NULL, commune TEXT NOT NULL, date_installation TEXT NOT NULL, statut TEXT NOT NULL);
CREATE TABLE employeurs (
  id_employeur TEXT PRIMARY KEY, raison_sociale TEXT NOT NULL, secteur_activite TEXT NOT NULL,
  effectif INTEGER, departement TEXT NOT NULL, commune TEXT NOT NULL);
CREATE TABLE assures (
  id_assure TEXT PRIMARY KEY, sexe TEXT NOT NULL, annee_naissance INTEGER NOT NULL, departement TEXT NOT NULL,
  code_postal TEXT NOT NULL, commune TEXT NOT NULL, regime TEXT NOT NULL,
  id_employeur TEXT REFERENCES employeurs(id_employeur), id_medecin_traitant TEXT REFERENCES professionnels_sante(id_ps),
  date_affiliation TEXT NOT NULL, salaire_journalier_base REAL);
CREATE TABLE arrets_travail (
  id_arret TEXT PRIMARY KEY, id_assure TEXT NOT NULL REFERENCES assures(id_assure),
  id_ps_prescripteur TEXT NOT NULL REFERENCES professionnels_sante(id_ps), type_risque TEXT NOT NULL,
  nature TEXT NOT NULL, id_arret_initial TEXT REFERENCES arrets_travail(id_arret),
  date_debut TEXT NOT NULL, date_fin TEXT NOT NULL, date_reception TEXT NOT NULL);
CREATE TABLE paiements_ij (
  id_paiement TEXT PRIMARY KEY, id_arret TEXT NOT NULL REFERENCES arrets_travail(id_arret),
  periode_debut TEXT NOT NULL, periode_fin TEXT NOT NULL, nb_jours INTEGER NOT NULL,
  montant_journalier REAL NOT NULL, montant_brut REAL NOT NULL, date_paiement TEXT NOT NULL, statut TEXT NOT NULL);
CREATE TABLE prestations (
  id_prestation TEXT PRIMARY KEY, id_assure TEXT NOT NULL REFERENCES assures(id_assure),
  id_ps TEXT NOT NULL REFERENCES professionnels_sante(id_ps), code_acte TEXT NOT NULL REFERENCES ref_actes(code_acte),
  date_soins TEXT NOT NULL, date_liquidation TEXT NOT NULL, montant_depense REAL NOT NULL,
  base_remboursement REAL NOT NULL, taux_applique INTEGER NOT NULL, montant_rembourse REAL NOT NULL);
CREATE TABLE controles (
  id_controle TEXT PRIMARY KEY, table_source TEXT NOT NULL, id_reference TEXT NOT NULL, type_anomalie TEXT NOT NULL,
  date_detection TEXT NOT NULL, montant_indu REAL NOT NULL, statut TEXT NOT NULL, date_cloture TEXT);


